/**
 * Migration tool: creates one route folder per inner page and blog post, e.g.
 *   src/app/pricing/page.tsx
 *   src/app/dive-sites/diving-amed/page.tsx
 *   src/app/couples-retreat/page.tsx        (post)
 * Each file loads its content JSON and its own original CSS.
 *
 *   node scripts/migration/generate-routes.mjs
 *
 * Existing page.tsx files are only overwritten if they still carry the
 * "Generated by" marker, so hand-written pages are never replaced.
 */
import { readdir, readFile, writeFile, mkdir, access } from "node:fs/promises";
import path from "node:path";

const MARKER = "// Generated by scripts/migration/generate-routes.mjs";

async function writeRoute(urlPath, code) {
  const dir = path.join("src/app", ...urlPath.split("/").filter(Boolean));
  const target = path.join(dir, "page.tsx");
  const existing = await readFile(target, "utf8").catch(() => null);
  if (existing !== null && !existing.startsWith(MARKER)) {
    console.log("keep hand-written", target);
    return false;
  }
  await mkdir(dir, { recursive: true });
  await writeFile(target, code);
  return true;
}

async function main() {
  let written = 0;

  for (const file of (await readdir("src/content/pages")).filter((f) => f.endsWith(".json"))) {
    const { path: urlPath, elementorId } = JSON.parse(await readFile(path.join("src/content/pages", file), "utf8"));
    const slug = file.replace(/\.json$/, "");
    const hasEael = await access(`src/styles/elementor/eael-${elementorId}.css`).then(() => true, () => false);
    const eaelImport = hasEael ? `
import "@/styles/elementor/eael-${elementorId}.css";` : "";
    const code = `${MARKER}
// Content: src/content/pages/${file} · Original CSS: src/styles/elementor/post-${elementorId}.css
import ElementorPage from "@/components/elementor/ElementorPage";
import type { PageContent } from "@/components/elementor/types";
import content from "@/content/pages/${slug}.json";
import { pageMetadata } from "@/lib/metadata";
import "@/styles/elementor/post-${elementorId}.css";${eaelImport}
import "@/components/elementor/styles-after";

export const metadata = pageMetadata("${urlPath}");

export default function Page() {
  return <ElementorPage page={content as PageContent} />;
}
`;
    if (await writeRoute(urlPath, code)) written++;
  }

  for (const file of (await readdir("src/content/posts").catch(() => [])).filter((f) => f.endsWith(".json"))) {
    const post = JSON.parse(await readFile(path.join("src/content/posts", file), "utf8"));
    const slug = file.replace(/\.json$/, "");
    const cssImports = [post.bannerId, ...post.embeddedElementorIds]
      .map((id) => `import "@/styles/elementor/post-${id}.css";`)
      .join("\n");
    const code = `${MARKER}
// Blog post. Content: src/content/posts/${file}
import PostPage, { type PostContent } from "@/components/elementor/PostPage";
import content from "@/content/posts/${slug}.json";
import { pageMetadata } from "@/lib/metadata";
${cssImports}
import "@/components/elementor/styles-after";

export const metadata = pageMetadata("${post.path}");

export default function Page() {
  return <PostPage post={content as PostContent} />;
}
`;
    if (await writeRoute(post.path, code)) written++;
  }

  console.log(`wrote ${written} route files`);
}

main();
